-- RuffNeck Social Hub 0.7.0: secure workspace invitations and role administration.
-- Apply only after migrations 0001 through 0005.
-- Invitation links are generated by the server and only SHA-256 token hashes
-- are stored in this table. Raw invitation tokens are never persisted.

create table if not exists public.workspace_invitations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  email text not null check (email = lower(btrim(email)) and position('@' in email) > 1),
  role public.workspace_role not null check (role in ('admin', 'manager', 'publisher', 'analyst', 'client_approver')),
  token_hash text not null unique check (length(token_hash) = 64),
  invited_by uuid not null references auth.users(id),
  expires_at timestamptz not null,
  accepted_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint workspace_invitation_expiry_after_creation check (expires_at > created_at)
);

create unique index if not exists workspace_invitations_one_pending_email_idx
  on public.workspace_invitations(workspace_id, email)
  where accepted_at is null and revoked_at is null;
create index if not exists workspace_invitations_workspace_created_idx
  on public.workspace_invitations(workspace_id, created_at desc);

alter table public.workspace_invitations enable row level security;
revoke all on table public.workspace_invitations from public, anon, authenticated;

create or replace function public.create_workspace_invitation(
  target_workspace_id uuid,
  target_email text,
  target_role text,
  target_token_hash text
)
returns table(invitation_id uuid, invitation_expires_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id uuid := auth.uid();
  actor_role public.workspace_role;
  clean_email text := pg_catalog.lower(pg_catalog.btrim(target_email));
  new_invitation_id uuid;
  prior_invitation_id uuid;
  prior_inviter_id uuid;
  prior_inviter_role public.workspace_role;
  new_expiry timestamptz := pg_catalog.now() + interval '7 days';
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if clean_email is null or clean_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'Enter a valid invitation email address' using errcode = '22023';
  end if;
  if target_token_hash is null or target_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid invitation token' using errcode = '22023';
  end if;
  if target_role is null or target_role not in ('admin', 'manager', 'publisher', 'analyst', 'client_approver') then
    raise exception 'This role cannot be invited' using errcode = '22023';
  end if;

  select m.role into actor_role
  from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = current_user_id;
  if actor_role is null then
    raise exception 'You are not a member of this workspace' using errcode = '42501';
  end if;
  if actor_role not in ('owner', 'admin', 'manager') then
    raise exception 'Your role cannot invite workspace members' using errcode = '42501';
  end if;
  if actor_role = 'manager' and target_role not in ('publisher', 'analyst', 'client_approver') then
    raise exception 'Managers can invite publishers, analysts and client approvers only' using errcode = '42501';
  end if;
  if actor_role = 'admin' and target_role = 'admin' then
    raise exception 'Only the workspace owner can invite another administrator' using errcode = '42501';
  end if;
  if exists (
    select 1 from auth.users u
    join public.workspace_members m on m.user_id = u.id
    where m.workspace_id = target_workspace_id and pg_catalog.lower(u.email) = clean_email
  ) then
    raise exception 'This person is already a workspace member' using errcode = '23505';
  end if;

  select i.id, i.invited_by, m.role into prior_invitation_id, prior_inviter_id, prior_inviter_role
  from public.workspace_invitations i
  left join public.workspace_members m
    on m.workspace_id = i.workspace_id and m.user_id = i.invited_by
  where i.workspace_id = target_workspace_id and i.email = clean_email
    and i.accepted_at is null and i.revoked_at is null
  order by i.created_at desc limit 1;
  if prior_inviter_id is not null then
    if prior_inviter_role = 'owner' and actor_role <> 'owner' then
      raise exception 'Only the workspace owner can replace an owner-issued invitation' using errcode = '42501';
    end if;
    if actor_role = 'manager' and prior_inviter_id <> current_user_id then
      raise exception 'Managers can replace only invitations they created' using errcode = '42501';
    end if;
  end if;

  if prior_invitation_id is not null then
    insert into public.audit_events (workspace_id, actor_user_id, event_type, resource_type, resource_id, outcome, safe_metadata)
    values (target_workspace_id, current_user_id, 'workspace.invitation_replaced', 'workspace_invitation', prior_invitation_id::text, 'success',
      pg_catalog.jsonb_build_object('replaced_by_role', target_role));
  end if;

  update public.workspace_invitations
  set revoked_at = pg_catalog.now()
  where workspace_id = target_workspace_id
    and email = clean_email
    and accepted_at is null
    and revoked_at is null;

  insert into public.workspace_invitations (
    workspace_id, email, role, token_hash, invited_by, expires_at
  ) values (
    target_workspace_id, clean_email, target_role::public.workspace_role,
    target_token_hash, current_user_id, new_expiry
  ) returning id into new_invitation_id;

  insert into public.audit_events (
    workspace_id, actor_user_id, event_type, resource_type,
    resource_id, outcome, safe_metadata
  ) values (
    target_workspace_id, current_user_id, 'workspace.invitation_created',
    'workspace_invitation', new_invitation_id::text, 'success',
    pg_catalog.jsonb_build_object('email', clean_email, 'role', target_role, 'expires_at', new_expiry)
  );

  return query select new_invitation_id, new_expiry;
end;
$$;

create or replace function public.preview_workspace_invitation(target_token_hash text)
returns table(
  invitation_id uuid,
  workspace_name text,
  invited_email text,
  invited_role text,
  invitation_expires_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select i.id, w.name, i.email, i.role::text, i.expires_at
  from public.workspace_invitations i
  join public.workspaces w on w.id = i.workspace_id
  where i.token_hash = target_token_hash
    and i.accepted_at is null
    and i.revoked_at is null
    and i.expires_at > pg_catalog.now()
  limit 1
$$;

create or replace function public.accept_workspace_invitation(target_token_hash text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id uuid := auth.uid();
  current_email text;
  invitation_row public.workspace_invitations%rowtype;
begin
  if current_user_id is null then
    raise exception 'Sign in before accepting this invitation' using errcode = '28000';
  end if;
  select pg_catalog.lower(u.email) into current_email from auth.users u where u.id = current_user_id;
  if current_email is null then
    raise exception 'The signed-in account has no email address' using errcode = '28000';
  end if;

  select * into invitation_row
  from public.workspace_invitations i
  where i.token_hash = target_token_hash
  for update;
  if not found then
    raise exception 'Invitation not found or no longer available' using errcode = 'P0002';
  end if;
  if invitation_row.revoked_at is not null or invitation_row.accepted_at is not null then
    raise exception 'This invitation has already been used or revoked' using errcode = '22023';
  end if;
  if invitation_row.expires_at <= pg_catalog.now() then
    raise exception 'This invitation has expired' using errcode = '22023';
  end if;
  if current_email <> invitation_row.email then
    raise exception 'Sign in with the email address this invitation was sent to' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.workspace_members m
    where m.workspace_id = invitation_row.workspace_id and m.user_id = current_user_id
  ) then
    raise exception 'You are already a member of this workspace' using errcode = '23505';
  end if;

  insert into public.workspace_members(workspace_id, user_id, role)
  values (invitation_row.workspace_id, current_user_id, invitation_row.role);

  update public.workspace_invitations
  set accepted_at = pg_catalog.now()
  where id = invitation_row.id;

  insert into public.audit_events (
    workspace_id, actor_user_id, event_type, resource_type,
    resource_id, outcome, safe_metadata
  ) values (
    invitation_row.workspace_id, current_user_id, 'workspace.invitation_accepted',
    'workspace_invitation', invitation_row.id::text, 'success',
    pg_catalog.jsonb_build_object('role', invitation_row.role::text)
  );

  return invitation_row.workspace_id;
end;
$$;

create or replace function public.list_workspace_team(target_workspace_id uuid)
returns table(member_user_id uuid, member_email text, member_role text, joined_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  actor_role public.workspace_role;
begin
  select m.role into actor_role
  from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = auth.uid();
  if actor_role is null or actor_role not in ('owner', 'admin', 'manager') then
    raise exception 'Your role cannot view the workspace team directory' using errcode = '42501';
  end if;
  return query
  select m.user_id, u.email::text, m.role::text, m.created_at
  from public.workspace_members m
  join auth.users u on u.id = m.user_id
  where m.workspace_id = target_workspace_id
  order by case m.role when 'owner' then 0 when 'admin' then 1 when 'manager' then 2 else 3 end,
           m.created_at asc;
end;
$$;

create or replace function public.list_workspace_invitations(target_workspace_id uuid)
returns table(
  invitation_id uuid,
  invited_email text,
  invited_role text,
  created_at timestamptz,
  expires_at timestamptz,
  accepted_at timestamptz,
  revoked_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  actor_role public.workspace_role;
begin
  select m.role into actor_role
  from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = auth.uid();
  if actor_role is null or actor_role not in ('owner', 'admin', 'manager') then
    raise exception 'Your role cannot view workspace invitations' using errcode = '42501';
  end if;
  return query
  select i.id, i.email, i.role::text, i.created_at, i.expires_at, i.accepted_at, i.revoked_at
  from public.workspace_invitations i
  where i.workspace_id = target_workspace_id
  order by i.created_at desc
  limit 50;
end;
$$;

create or replace function public.revoke_workspace_invitation(target_invitation_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id uuid := auth.uid();
  invitation_row public.workspace_invitations%rowtype;
  actor_role public.workspace_role;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select * into invitation_row from public.workspace_invitations i
  where i.id = target_invitation_id for update;
  if not found then raise exception 'Invitation not found' using errcode = 'P0002'; end if;
  select m.role into actor_role from public.workspace_members m
  where m.workspace_id = invitation_row.workspace_id and m.user_id = current_user_id;
  if actor_role is null or actor_role not in ('owner', 'admin') then
    raise exception 'Only owners and administrators can revoke invitations' using errcode = '42501';
  end if;
  if invitation_row.accepted_at is not null or invitation_row.revoked_at is not null then
    raise exception 'This invitation is no longer pending' using errcode = '22023';
  end if;
  update public.workspace_invitations set revoked_at = pg_catalog.now() where id = target_invitation_id;
  insert into public.audit_events(workspace_id, actor_user_id, event_type, resource_type, resource_id, outcome)
  values (invitation_row.workspace_id, current_user_id, 'workspace.invitation_revoked', 'workspace_invitation', target_invitation_id::text, 'success');
end;
$$;

create or replace function public.set_workspace_member_role(
  target_workspace_id uuid,
  target_member_user_id uuid,
  target_role text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id uuid := auth.uid();
  actor_role public.workspace_role;
  previous_role public.workspace_role;
begin
  if current_user_id is null then raise exception 'Authentication required' using errcode = '28000'; end if;
  if target_role is null or target_role not in ('admin', 'manager', 'publisher', 'analyst', 'client_approver') then
    raise exception 'Invalid workspace role' using errcode = '22023';
  end if;
  select m.role into actor_role from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = current_user_id;
  if actor_role is null or actor_role not in ('owner', 'admin') then
    raise exception 'Only owners and administrators can change member roles' using errcode = '42501';
  end if;
  if target_member_user_id = current_user_id then
    raise exception 'You cannot change your own workspace role' using errcode = '22023';
  end if;
  select m.role into previous_role from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = target_member_user_id
  for update;
  if previous_role is null then raise exception 'Workspace member not found' using errcode = 'P0002'; end if;
  if previous_role = 'owner' then raise exception 'The workspace owner role cannot be changed here' using errcode = '42501'; end if;
  if actor_role = 'admin' and (previous_role = 'admin' or target_role = 'admin') then
    raise exception 'Only the workspace owner can change administrator roles' using errcode = '42501';
  end if;
  update public.workspace_members set role = target_role::public.workspace_role
  where workspace_id = target_workspace_id and user_id = target_member_user_id;
  insert into public.audit_events(workspace_id, actor_user_id, event_type, resource_type, resource_id, outcome, safe_metadata)
  values (target_workspace_id, current_user_id, 'workspace.member_role_changed', 'workspace_member', target_member_user_id::text, 'success',
    pg_catalog.jsonb_build_object('previous_role', previous_role::text, 'new_role', target_role));
end;
$$;

create or replace function public.remove_workspace_member(target_workspace_id uuid, target_member_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id uuid := auth.uid();
  actor_role public.workspace_role;
  target_role public.workspace_role;
begin
  if current_user_id is null then raise exception 'Authentication required' using errcode = '28000'; end if;
  if target_member_user_id = current_user_id then
    raise exception 'Ask another workspace administrator to remove your membership' using errcode = '22023';
  end if;
  select m.role into actor_role from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = current_user_id;
  if actor_role is null or actor_role not in ('owner', 'admin') then
    raise exception 'Only owners and administrators can remove workspace members' using errcode = '42501';
  end if;
  select m.role into target_role from public.workspace_members m
  where m.workspace_id = target_workspace_id and m.user_id = target_member_user_id
  for update;
  if target_role is null then raise exception 'Workspace member not found' using errcode = 'P0002'; end if;
  if target_role = 'owner' or (actor_role = 'admin' and target_role = 'admin') then
    raise exception 'You do not have permission to remove this member' using errcode = '42501';
  end if;
  delete from public.workspace_members
  where workspace_id = target_workspace_id and user_id = target_member_user_id;
  insert into public.audit_events(workspace_id, actor_user_id, event_type, resource_type, resource_id, outcome, safe_metadata)
  values (target_workspace_id, current_user_id, 'workspace.member_removed', 'workspace_member', target_member_user_id::text, 'success',
    pg_catalog.jsonb_build_object('previous_role', target_role::text));
end;
$$;

revoke all on function public.create_workspace_invitation(uuid, text, text, text) from public, anon;
revoke all on function public.preview_workspace_invitation(text) from public;
revoke all on function public.accept_workspace_invitation(text) from public, anon;
revoke all on function public.list_workspace_team(uuid) from public, anon;
revoke all on function public.list_workspace_invitations(uuid) from public, anon;
revoke all on function public.revoke_workspace_invitation(uuid) from public, anon;
revoke all on function public.set_workspace_member_role(uuid, uuid, text) from public, anon;
revoke all on function public.remove_workspace_member(uuid, uuid) from public, anon;

grant execute on function public.create_workspace_invitation(uuid, text, text, text) to authenticated;
grant execute on function public.preview_workspace_invitation(text) to anon, authenticated;
grant execute on function public.accept_workspace_invitation(text) to authenticated;
grant execute on function public.list_workspace_team(uuid) to authenticated;
grant execute on function public.list_workspace_invitations(uuid) to authenticated;
grant execute on function public.revoke_workspace_invitation(uuid) to authenticated;
grant execute on function public.set_workspace_member_role(uuid, uuid, text) to authenticated;
grant execute on function public.remove_workspace_member(uuid, uuid) to authenticated;

comment on table public.workspace_invitations is 'One-time workspace invitations. Only token hashes are stored; raw invitation links are generated server-side.';
comment on function public.accept_workspace_invitation(text) is 'Accepts an unexpired invitation only when the authenticated user email matches the invitation email.';
